\echo '=== ALT1 small category, ids resolved in app, IN (UNION ALL)'
EXPLAIN (ANALYZE, BUFFERS) SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE p.id IN (SELECT id FROM catalog_product WHERE primary_category_id = ANY('{70134891-dc80-5215-9109-23f8f80ad40a,50cd3ab9-6263-5441-9d77-cef1c8794964,d2a8f52e-6be4-54e2-afa2-b6537de3abe3,dad8249a-d4d2-5f77-a4ed-c20fad01e574,830597e3-c1d9-53b5-ac6c-9d8b19076ffd}'::uuid[]) UNION ALL SELECT product_id FROM catalog_product_category WHERE category_id = ANY('{70134891-dc80-5215-9109-23f8f80ad40a,50cd3ab9-6263-5441-9d77-cef1c8794964,d2a8f52e-6be4-54e2-afa2-b6537de3abe3,dad8249a-d4d2-5f77-a4ed-c20fad01e574,830597e3-c1d9-53b5-ac6c-9d8b19076ffd}'::uuid[])) ORDER BY p.name, p.id LIMIT 26;
\echo '=== ALT2 leaf 21k'
EXPLAIN (ANALYZE, BUFFERS) SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE p.id IN (SELECT id FROM catalog_product WHERE primary_category_id = ANY('{4b68d4ca-f126-562f-a142-65edd596cc0c}'::uuid[]) UNION ALL SELECT product_id FROM catalog_product_category WHERE category_id = ANY('{4b68d4ca-f126-562f-a142-65edd596cc0c}'::uuid[])) ORDER BY p.name, p.id LIMIT 26;
