\echo '=== ALT4 hybrid search: GIN matches then sort (termos)'
EXPLAIN (ANALYZE, BUFFERS) WITH m AS MATERIALIZED (SELECT p.id, p.name, p.tax_class, p.updated_at FROM catalog_product p WHERE p.name ILIKE '%termos%' LIMIT 10001) SELECT * FROM m ORDER BY name, id LIMIT 26;
